{
  "source": "验尸官的婚礼",
  "lang": "zh",
  "params": {
    "episodes": 60,
    "minutesPerEpisode": 1.5,
    "genre": "女频大女主复仇悬疑（豪门）",
    "adaptMode": "抽核",
    "preferences": [
      "每集拿出一样看得见的证据",
      "爽点落在沈家与周启年脸上",
      "结局：当庭推翻自己签的报告，墓前放表"
    ]
  },
  "adaptation": {
    "core": "被退婚的女法医在前未婚夫的婚礼上认出新郎是替身，用一件件看得见的证据把三年前那具无名男尸还原成沈峥，最后亲手推翻自己签过的假报告。",
    "keep": [
      {
        "what": "婚礼认替身的开局",
        "why": "第一集就有全剧最强的钩子，前未婚夫的婚礼天然自带羞辱与反击",
        "evidence": "一眼认出新郎是替身：真新郎三年前就躺在她的解剖台上。"
      },
      {
        "what": "每集一件证据的推进引擎",
        "why": "证据是可拍的实物，AI 生成好控；证据递进=疤→切片→报告→录音→袖扣，五段一段一件主证",
        "evidence": "每一集她都要拿出一样看得见的证据：一道疤、一张切片、一段录音。"
      },
      {
        "what": "林晚自己签过假报告这根刺",
        "why": "让女主不是完美受害者，越接近真相越接近自己的罪，中点和结局都压在这里",
        "evidence": "被周启年逼着改成“意外”，签了字，这是她心里的一根刺。"
      },
      {
        "what": "苏曼丽的房卡与一次反水",
        "why": "敌营里的不稳定盟友，给中段制造一次真失守",
        "evidence": "答谢宴上偷偷把求救的房卡塞给她；为了家里的生意，后面还会反水一次。"
      }
    ],
    "cut": [
      {
        "what": "苏沈港口生意的商战线",
        "why": "两分钟一集装不下商战，港口只作为洗钱证据的来源，不单独开线"
      },
      {
        "what": "林晚与沈砚的感情线",
        "why": "大女主复仇剧，沈砚定位内应与证人，不发展恋爱，避免稀释沈峥这根主线"
      },
      {
        "what": "沈家二房争股份的支线",
        "why": "遗嘱只作为宋婉仪找替身的动机交代一次，二房不出场"
      },
      {
        "what": "程野的赌债债主线",
        "why": "只作为他被宋家拿捏的背景，债主不出场，拿捏他的筹码统一换成妹妹"
      }
    ],
    "merge": [
      {
        "what": "宋家的司机、打手、买通的鉴定人统一并入一个保镖",
        "why": "宋知远的脏手只需要一张脸"
      },
      {
        "what": "办案警察并成一位刑侦队长",
        "why": "后半程的布控、审讯、移送都由同一人承担，观众好认"
      },
      {
        "what": "法医中心的同事并成一位实习法医",
        "why": "送检链见证人、林晚停职后的内线，同一功能"
      }
    ],
    "risks": [
      {
        "what": "程野与沈峥同脸，AI 生成容易混",
        "plan": "共用一张脸资产，用左手虎口有无疤和白手套区分；沈峥只在闪回出现，闪回统一冷蓝调"
      },
      {
        "what": "解剖与尸体画面过不了平台审核",
        "plan": "尸体全程白布不露脸，用切片、报告、尸检照片局部、虎口特写替代"
      },
      {
        "what": "证据引擎重复，观众疲劳",
        "plan": "五段每段换一类主证（疤/切片/报告/录音/袖扣），沈家毁证手段也逐段升级：抹黑→毁样本→停职→灭口→杀人"
      },
      {
        "what": "游艇夜海戏生成难",
        "plan": "三年前闪回与终局对峙共用同一游艇资产，只换时段；落水只拍入水前一刻"
      }
    ],
    "cutNote": "这意味着：全剧只有一条主线——三年前是谁杀了沈峥，副线是林晚自己的假报告；终点不是夺回沈氏，而是她当庭重写死因并签上自己的名字。",
    "mergeNote": "主角组定林晚、程野、沈砚、宋知远四人——林晚从签假报告到亲手推翻，程野从替人活到替自己认罪，沈砚从不信到作证，宋知远是全剧最后的对手。周启年、宋婉仪、苏曼丽是被爽点打脸的配角，不进主角组。"
  },
  "characters": [
    {
      "id": "C01",
      "name": "林晚",
      "role": "女主 · 法医",
      "tier": "lead",
      "arc": "从被退婚、被抹黑、被停职，到当庭推翻自己三年前签的报告，重写死者沈峥他杀并签名——赢回的不是名声，是那份签字",
      "from": ["选题卡 林晚"]
    },
    {
      "id": "C02",
      "name": "程野",
      "role": "顶着沈峥的脸的替身新郎",
      "tier": "lead",
      "arc": "从替死人活、怕自己哪天也意外，到交出生活手册作证，最后带着妹妹去自首",
      "from": ["选题卡 程野"]
    },
    {
      "id": "C03",
      "name": "沈砚",
      "role": "沈家二少 · 林晚在沈家的内应",
      "tier": "lead",
      "arc": "从不信法医、嘲讽林晚，到用自己的血做亲缘比对，再到想起游艇那晚并出庭作证",
      "from": ["选题卡 沈砚"]
    },
    {
      "id": "C04",
      "name": "宋知远",
      "role": "主反派 · 沈家舅舅",
      "tier": "lead",
      "arc": "前半程是和气的调停人，第33集袖扣露底，最后在同一艘游艇上被当场拿下，认罪伏法",
      "from": ["选题卡 宋知远"]
    },
    {
      "id": "C05",
      "name": "苏曼丽",
      "role": "新娘 · 敌营里不稳定的盟友",
      "tier": "support",
      "arc": "带头踩林晚→塞房卡求救→为生意反水→被宋知远当替罪羊后交出港口货单",
      "from": ["选题卡 苏曼丽"]
    },
    {
      "id": "C06",
      "name": "周启年",
      "role": "法医中心主任 · 三年前逼签的人",
      "tier": "support",
      "arc": "从压林晚的老领导，到被她当众反将、被宋知远灭口未遂，最后交出录音认罪",
      "from": ["选题卡 周启年"]
    },
    {
      "id": "C07",
      "name": "宋婉仪",
      "role": "沈家主母",
      "tier": "support",
      "arc": "为保股份找人顶替儿子、一路护着替身；得知儿子死于亲弟之手后崩塌，交出账本与沈氏",
      "from": ["选题卡 宋婉仪"]
    },
    {
      "id": "C08",
      "name": "沈峥",
      "role": "死者 · 只活在闪回与证据里",
      "tier": "support",
      "arc": "订婚时送表的人、发现洗钱的人、游艇上被灭口的人；每一段闪回补一块他的死因",
      "from": ["选题卡 沈峥（与程野共用同一张脸资产，以虎口疤区分）"]
    },
    {
      "id": "C09",
      "name": "程溪",
      "role": "程野的妹妹 · 宋知远的筹码",
      "tier": "support",
      "arc": "被宋家安置在外当人质，苏曼丽反水后被带走，终局获救，陪哥哥去自首",
      "from": ["选题卡结局「程野带着妹妹去自首」", "原创：补出名字与人质功能，替换赌债线"]
