      "name": "审判长",
      "role": "终局庭审",
      "tier": "functional",
      "from": ["原创"]
    }
  ],
  "scenes": [
    { "id": "S01", "name": "沈家婚礼宴会厅（婚礼 / 答谢宴 / 发布会）", "primary": true },
