    { "id": "S03", "name": "周启年主任办公室", "primary": true },
    { "id": "S04", "name": "沈家老宅客厅", "primary": true },
    { "id": "S05", "name": "酒店新婚套房", "primary": true },
    { "id": "S06", "name": "沈家游艇（三年前夜 / 终局夜）", "primary": true },
    { "id": "S07", "name": "林晚公寓", "primary": true },
    { "id": "S08", "name": "宋氏港口码头办公室", "primary": true },
    { "id": "S09", "name": "法庭", "primary": true },
    {
